// wrapCueRawString wraps raw CUE content in a #"""..."""# string literal.
func wrapCueRawString(content string) *ast.BasicLit {
	var sb strings.Builder
	sb.WriteString(`#"""`)
	sb.WriteString("\n")
	sb.WriteString(content)
	sb.WriteString("\n")
	sb.WriteString(`"""#`)
	result := strings.ReplaceAll(sb.String(), "\t", "  ")
